def name_operands(region,function_address,operation):
    if region=='Action' and function_address==0xE4DB:
        operation=operation.replace('AND #F0','AND @ActionVertexCodeConst.InverseMask')
        operation=operation.replace('AND #0F','AND @ActionPolygonConst.OutsideMask')
    return operation
